def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    own = [h[0] for h in history]
    last_opp = opp[-1]
    last_own = own[-1]

    # Count total defections quickly
    opp_d = 0
    own_d = 0
    for i in range(n):
        if opp[i] == 'D':
            opp_d += 1
        if own[i] == 'D':
            own_d += 1

    # Endgame: secure extra payoff in last rounds, but only if opponent
    # has shown signs of defection or we're behind; pure cooperators are
    # worth keeping cooperative until the very end if they punish.
    remaining = 100 - n
    if remaining <= 3:
        if opp_d >= 1 or n >= 99:
            return 'D'
        if remaining == 1:
            return 'D'
        return 'C'

    # Detect sustained defection early and stop feeding it.
    if opp_d >= 3 and opp_d * 2 >= n:
        # If opponent never cooperated after the start, defect.
        # Occasionally probe with C to test for forgiveness.
        if opp_d >= n - 1:
            return 'D'
        if rng.random() < 0.06:
            return 'C'
        return 'D'

    # Consecutive opponent defections at end
    consec = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'D':
            consec += 1
        else:
            break

    # Strong, immediate retaliation for sustained defection.
    if consec >= 3:
        # If we've already retaliated several times, mix in forgiveness
        own_consec_d = 0
        for i in range(n - 1, -1, -1):
            if own[i] == 'D':
                own_consec_d += 1
            else:
                break
        if own_consec_d >= 3 and rng.random() < 0.2:
            return 'C'
        return 'D'

    if last_opp == 'D':
        # Single or double defection: retaliate, but forgive quickly
        # to restore mutual cooperation with TFT-like opponents.
        if consec == 1:
            # If we cooperated last round, defect once.
            if last_own == 'C':
                return 'D'
            # We already retaliated; return to cooperation to test.
            return 'C'
        # consec == 2
        if last_own == 'C':
            return 'D'
        # We defected last round; one more retaliation then forgive.
        if n >= 2 and own[-2] == 'D':
            return 'C'
        return 'D'

    # Opponent cooperated last round.
    # If we defected and they still cooperated, reward with cooperation
    # to regain mutual CC against forgiving opponents.
    if last_own == 'D':
        return 'C'

    # Early game: mostly cooperate to establish mutual cooperation.
    if n < 6:
        # Very light probe against pure cooperators is not worth much.
        return 'C'

    # Classify opponent by recent behavior
    window = 8
    start = n - window if n > window else 0
    recent_opp_d = 0
    for i in range(start, n):
        if opp[i] == 'D':
            recent_opp_d += 1

    opp_rate = opp_d / float(n)

    # Highly cooperative opponent: cooperate, with rare exploitation
    # only when safe (no recent defection and not near end).
    if opp_rate <= 0.15 and recent_opp_d <= 1:
        # Occasional exploitation to gain 5 vs 3, but only if we are
        # reasonably safe and not provoking a retaliator.
        if recent_opp_d == 0 and n > 12 and n < 90:
            if rng.random() < 0.08:
                return 'D'
        return 'C'

    # Moderately cooperative: cooperate unless recently defected.
    if opp_rate <= 0.35:
        if recent_opp_d <= 1:
            return 'C'
        return 'D'

    # Moderately defective: defect more, occasional cooperation to test.
    if opp_rate <= 0.7:
        if last_opp == 'C' and recent_opp_d <= 2:
            if rng.random() < 0.5:
                return 'C'
            return 'D'
        return 'D'

    # Mostly defective: defect, rarely probe.
    if rng.random() < 0.04:
        return 'C'
    return 'D'
